import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Mesh, 
  Group, 
  SRGBColorSpace 
} from 'three/webgpu';
import { 
  texture, uv, vec3, vec4, float, mix, Fn, fract, sin, sub, add, mul
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-features-card-3';

  const pos = (config && config.scenePosition) || [3.2, -0.3, 0];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const metalTex = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  if ('colorSpace' in metalTex) metalTex.colorSpace = SRGBColorSpace;

  const inkCol = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surfaceCol = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
  const accentCol = vec3(0xff / 255, 0x2a / 255, 0x38 / 255);

  const colorFn = Fn(() => {
    const t = texture(metalTex, uv());
    const grad = mix(inkCol, surfaceCol, uv().y);
    const metalTint = mix(t.rgb, grad, float(0.34));
    const n = fract(sin(uv().x.mul(12.9898).add(uv().y.mul(78.233))).mul(43758.5453));
    const grain = sub(n, float(0.5)).mul(0.045);
    const accentEdge = smoothstep(float(0.0), float(0.012), uv().x).mul(
      smoothstep(float(0.0), float(0.012), sub(float(1.0), uv().x))
    );
    const edgeMask = sub(float(1.0), accentEdge);
    const withEdge = mix(accentCol.mul(0.6), metalTint.add(grain), edgeMask);
    return vec4(withEdge, float(1.0));
  });

  const material = new MeshBasicNodeMaterial();
  material.colorNode = colorFn();
  material.transparent = false;

  const cardWidth = 1.4;
  const cardHeight = cardWidth * (320 / 512);
  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const mesh = new Mesh(geometry, material);
  mesh.name = 'hub-features-card-3-plane';
  group.add(mesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (metalTex && typeof metalTex.dispose === 'function') {
      metalTex.dispose();
    }
  };

  return group;
}
